from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient

class AzureMonitorClient:
    def __init__(self):
        self.credential = DefaultAzureCredential()

    def get_metrics_query_client(self):
        return MetricsQueryClient(self.credential)

from datetime import datetime, timedelta, timezone
from observability_client import AzureMonitorClient
from azure.monitor.query import MetricAggregationType


def aggregate_metric_stats(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    client = AzureMonitorClient().get_metrics_query_client()

    aggregations = [MetricAggregationType.from_str(agg.upper()) for agg in payload.get('aggregations', ['average'])]

    result = client.query_resource(
        config['resource_id'],
        metric_names=[payload['metric']],
        timespan=(start, end),
        granularity=timedelta(seconds=config.get('period_seconds', 60)),
        aggregations=aggregations
    )

    aggregated_data = {}
    for metric in result.metrics:
        for series in metric.timeseries:
            for point in series.data:
                for agg_type in aggregations:
                    agg_value = getattr(point, agg_type.value.lower(), None)
                    if agg_value is not None:
                        if agg_type.value not in aggregated_data:
                            aggregated_data[agg_type.value] = []
                        aggregated_data[agg_type.value].append({
                            'timestamp': point.timestamp.timestamp(),
                            'value': float(agg_value)
                        })

    for agg_type in aggregated_data:
        aggregated_data[agg_type] = sorted(aggregated_data[agg_type], key=lambda p: p['timestamp'])

    return aggregated_data

from datetime import datetime, timedelta, timezone
from observability_client import AzureMonitorClient
from azure.monitor.query import MetricAggregationType


def filter_metric_dimensions(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    client = AzureMonitorClient().get_metrics_query_client()

    filters = []
    if 'dimensions' in payload:
        for dim_name, dim_value in payload['dimensions'].items():
            filters.append(f"{dim_name} eq '{dim_value}'")

    filter_str = " and ".join(filters) if filters else None

    result = client.query_resource(
        config['resource_id'],
        metric_names=[payload['metric']],
        timespan=(start, end),
        granularity=timedelta(seconds=config.get('period_seconds', 60)),
        aggregations=[MetricAggregationType.AVERAGE],
        filter=filter_str
    )

    points = [{'timestamp': point.timestamp.timestamp(), 'value': float(point.average),
               'dimensions': series.metadata}
              for metric in result.metrics for series in metric.timeseries
              for point in series.data if point.average is not None]

    return {'points': sorted(points, key=lambda point: point['timestamp'])}

import os
from openai import AzureOpenAI

def metric_summary(payload, config=None):
    config = config or {}
    client = AzureOpenAI(
        azure_endpoint=os.environ.get("AZURE_OPENAI_ENDPOINT"),
        api_key=os.environ.get("AZURE_OPENAI_API_KEY"),
        api_version="2024-02-15-preview"
    )

    metric_data_str = str(payload.get('metric_data'))
    prompt = f"Summarize the following metric data and highlight any trends or anomalies: {metric_data_str}"

    response = client.chat.completions.create(
        model=config.get('azure_openai_model', 'gpt-4o'),
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes metric data."},
            {"role": "user", "content": prompt}
        ]
    )
    return {'summary': response.choices[0].message.content}
